--- a/relayer-cli/src/utils/hashiHelpers/envioQueries.ts
+++ b/relayer-cli/src/utils/hashiHelpers/envioQueries.ts
@@ -1,136 +1,245 @@
 import request from "graphql-request";
 import { DispatchedTxnData, HashiMessageExecutionVars } from "./hashiTypes";
 import { DataError, MissingEnvironmentVariable } from "../errors";

 const DEFAULT_BATCH_SIZE = 10;
+// Page size used when draining every matching event of a single block. Chosen well
+// above the batch size so the common case costs exactly one extra request.
+const BLOCK_DRAIN_PAGE_SIZE = 100;

 interface EnvioMessageDispatched {
+  id: string;
   messageId: string;
   txHash: string;
   sourceChainId: string;
   yaho: string;
   nonce: string;
   targetChainId: string;
   threshold: string;
   sender: string;
   receiver: string;
   data: string;
   reporters: string;
   adapters: string;
   blockNumber: string;
   blockTimestamp: string;
 }

 interface EnvioDispatchedResponse {
   MessageDispatched: EnvioMessageDispatched[];
   chain_metadata: { latest_processed_block: number }[];
 }

+interface EnvioBlockEventsResponse {
+  MessageDispatched: EnvioMessageDispatched[];
+}
+
+// `id` is requested purely as a deterministic tie-breaker: without a secondary sort
+// key the indexer may order rows sharing a blockNumber arbitrarily between calls,
+// which would make the block-drain below unsound.
 const dispatchedMessagesQuery = `
   query DispatchedMessages($sourceChainId: numeric!, $targetChainId: numeric!, $chainId: Int!, $yaho: String!, $fromBlock: numeric!, $limit: Int!) {
     MessageDispatched(
       where: {
         sourceChainId: { _eq: $sourceChainId }
         targetChainId: { _eq: $targetChainId }
         yaho: { _ilike: $yaho }
         blockNumber: { _gt: $fromBlock }
       }
-      order_by: { blockNumber: asc }
+      order_by: { blockNumber: asc, id: asc }
       limit: $limit
     ) {
+      id
       messageId
       txHash
       sourceChainId
       yaho
       nonce
       targetChainId
       threshold
       sender
       receiver
       data
       reporters
       adapters
       blockNumber
       blockTimestamp
     }
     chain_metadata(where: { chain_id: { _eq: $chainId } }) {
       latest_processed_block
     }
   }
 `;

+// Fetches every matching event of one exact block, paginated with limit/offset so a
+// block holding more events than the batch size is still returned in full.
+const blockEventsQuery = `
+  query BlockDispatchedMessages($sourceChainId: numeric!, $targetChainId: numeric!, $yaho: String!, $blockNumber: numeric!, $limit: Int!, $offset: Int!) {
+    MessageDispatched(
+      where: {
+        sourceChainId: { _eq: $sourceChainId }
+        targetChainId: { _eq: $targetChainId }
+        yaho: { _ilike: $yaho }
+        blockNumber: { _eq: $blockNumber }
+      }
+      order_by: { blockNumber: asc, id: asc }
+      limit: $limit
+      offset: $offset
+    ) {
+      id
+      messageId
+      txHash
+      sourceChainId
+      yaho
+      nonce
+      targetChainId
+      threshold
+      sender
+      receiver
+      data
+      reporters
+      adapters
+      blockNumber
+      blockTimestamp
+    }
+  }
+`;
+
 /**
  * Map an Envio MessageDispatched row to the executor's HashiMessageExecutionVars shape.
  * @param row The raw MessageDispatched entity returned by the Envio indexer
  * @returns The HashiMessageExecutionVars for the executor
  */
 function toHashiMessageExecutionVars(row: EnvioMessageDispatched): HashiMessageExecutionVars {
   return {
     txHash: row.txHash,
     timestamp: Number(row.blockTimestamp),
     blockNumber: Number(row.blockNumber),
     messageId: BigInt(row.messageId),
     message: {
       nonce: Number(row.nonce),
       sender: row.sender,
       targetChainId: Number(row.targetChainId),
       receiver: row.receiver,
       threshold: Number(row.threshold),
       data: row.data,
       reporters: JSON.parse(row.reporters),
       adapters: JSON.parse(row.adapters),
     },
   };
 }

+/**
+ * Fetch every matching MessageDispatched event of one exact block, paginating internally
+ * until a short page comes back. A block is only safe to checkpoint past once it has been
+ * drained in full, otherwise events beyond the batch limit are skipped forever by the
+ * `blockNumber > fromBlock` cursor of the next call.
+ * @param envioEndpoint The Envio GraphQL endpoint
+ * @param sourceChainId The chain ID of the Yaho (source) chain
+ * @param targetChainId The chain ID the messages are destined for
+ * @param yahoAddress The Yaho contract address
+ * @param blockNumber The exact source-chain block number to drain
+ * @returns Every matching raw MessageDispatched row in that block
+ */
+async function fetchAllEventsInBlock(
+  envioEndpoint: string,
+  sourceChainId: number,
+  targetChainId: number,
+  yahoAddress: string,
+  blockNumber: number
+): Promise<EnvioMessageDispatched[]> {
+  const rows: EnvioMessageDispatched[] = [];
+  let offset = 0;
+  for (;;) {
+    const page = (await request(envioEndpoint, blockEventsQuery, {
+      sourceChainId,
+      targetChainId,
+      yaho: yahoAddress,
+      blockNumber,
+      limit: BLOCK_DRAIN_PAGE_SIZE,
+      offset,
+    })) as EnvioBlockEventsResponse;
+    const pageRows = page?.MessageDispatched ?? [];
+    rows.push(...pageRows);
+    if (pageRows.length < BLOCK_DRAIN_PAGE_SIZE) break;
+    offset += BLOCK_DRAIN_PAGE_SIZE;
+  }
+  return rows;
+}
+
 /**
  * Get MessageDispatched events from the Envio Yaho indexer starting after a specific block
  * @param sourceChainId The chain ID of the Yaho (source) chain
  * @param targetChainId The chain ID the messages are destined for; other routes' messages are excluded
  * @param yahoAddress The Yaho contract address
  * @param fromBlock The last processed block number; only events strictly after it are returned
- * @param batchSize The maximum number of messages to fetch (default: 10)
- * @returns The dispatched messages and the block number to checkpoint in the state file
+ * @param batchSize The maximum number of messages to fetch per page (default: 10). When the
+ *   page is full, the checkpoint block is drained in full, so the returned array may hold
+ *   more than batchSize messages.
+ * @returns The dispatched messages and the block number to checkpoint in the state file.
+ *   `toBlock` is always a plain block number, fully fetched up to and including that block.
  */
 async function getDispatchedMessagesFromEnvio(
   sourceChainId: number,
   targetChainId: number,
   yahoAddress: string,
   fromBlock: number,
   batchSize = DEFAULT_BATCH_SIZE
 ): Promise<DispatchedTxnData> {
   const envioEndpoint = process.env.RELAYER_ENVIO_YAHO;
   if (!envioEndpoint) {
     throw new MissingEnvironmentVariable("RELAYER_ENVIO_YAHO");
   }
   try {
     const result = (await request(envioEndpoint, dispatchedMessagesQuery, {
       sourceChainId,
       targetChainId,
       chainId: sourceChainId,
       yaho: yahoAddress,
       fromBlock,
       limit: batchSize,
     })) as EnvioDispatchedResponse;

-    const txns = result.MessageDispatched.map(toHashiMessageExecutionVars);
+    let txns = result.MessageDispatched.map(toHashiMessageExecutionVars);

     // A full batch may have been truncated mid-range, so only checkpoint up to
     // the last fetched message; otherwise the indexer head is safe to checkpoint.
     const indexerHead = result.chain_metadata[0]?.latest_processed_block;
     let toBlock = fromBlock;
-    if (txns.length === batchSize) {
-      toBlock = txns[txns.length - 1].blockNumber;
+    if (txns.length > 0 && txns.length === batchSize) {
+      // The batch is full, so the last block may have been cut off mid-block. Drain it
+      // completely before checkpointing past it: the next call filters on
+      // `blockNumber > toBlock`, so any event of that block left behind here is lost.
+      const lastBlock = txns[txns.length - 1].blockNumber;
+      const drained = (
+        await fetchAllEventsInBlock(envioEndpoint, sourceChainId, targetChainId, yahoAddress, lastBlock)
+      ).map(toHashiMessageExecutionVars);
+
+      // Union the drained rows with what the page already returned for that block, keyed
+      // by messageId, so a degraded/racing drain response can never drop a known event.
+      const lastBlockTxns: HashiMessageExecutionVars[] = [];
+      const seen = new Set<string>();
+      for (const txn of [...drained, ...txns.filter((t) => t.blockNumber === lastBlock)]) {
+        const key = txn.messageId.toString();
+        if (seen.has(key)) continue;
+        seen.add(key);
+        lastBlockTxns.push(txn);
+      }
+
+      // The returned array can legitimately exceed batchSize when a single block holds an
+      // unusual number of matching events; that is intentional, dropping them is not.
+      txns = [...txns.filter((t) => t.blockNumber !== lastBlock), ...lastBlockTxns];
+      toBlock = lastBlock;
     } else if (indexerHead !== undefined) {
       toBlock = Math.max(indexerHead, fromBlock);
     } else if (txns.length > 0) {
       toBlock = txns[txns.length - 1].blockNumber;
     }

     return { txns, toBlock };
   } catch (e) {
     throw new DataError("Failed to fetch dispatched messages (envio)", sourceChainId, "hashi", { cause: e });
   }
 }

 export { getDispatchedMessagesFromEnvio, toHashiMessageExecutionVars, EnvioMessageDispatched };

